const webhook  = $('Webhook Trigger').item.json.body;
const asset    = $('Fetch Asset DB').item.json;
const nvd      = $('Query NVD').item.json;
const epssRaw  = $input.item.json?.data?.[0]?.epss;

const vuln     = nvd.vulnerabilities?.[0]?.cve;
const cvssScore = vuln?.metrics?.cvssMetricV31?.[0]?.cvssData?.baseScore
               ?? vuln?.metrics?.cvssMetricV30?.[0]?.cvssData?.baseScore
               ?? vuln?.metrics?.cvssMetricV40?.[0]?.cvssData?.baseScore
               ?? vuln?.metrics?.cvssMetricV2?.[0]?.cvssData?.baseScore
               ?? 0;
const kevStatus = Boolean(vuln?.cisaExploitAdd);

const cvssNorm  = cvssScore / 10.0;
const epssScore = parseFloat(epssRaw) || 0.0;
const kevScore  = kevStatus ? 1.0 : 0.0;
const critNorm  = parseFloat(asset.crit_norm) || 0.0;
const expScore  = asset.exposicion_internet ? 1.0 : 0.0;

const rawIrc = (0.15 * cvssNorm) + (0.25 * epssScore) +
               (0.30 * kevScore) + (0.20 * critNorm)  + (0.10 * expScore);
const ircFinal = parseFloat(rawIrc.toFixed(4));

let prioridad = 'INFORMATIVA';
if (ircFinal >= 0.70)      prioridad = 'CRITICA';
else if (ircFinal >= 0.40) prioridad = 'ALTA';

return [{
  json: {
    activo_id:              asset.activo_id,
    cve_id:                 webhook.cve_id,
    hostname:               asset.hostname,
    exposicion_internet:    asset.exposicion_internet,
    crit_norm:              critNorm,
    cvss_score:             cvssScore,
    epss_score:             epssScore,
    kev_status:             kevStatus,
    irc_score:              ircFinal,
    prioridad,
    fecha_publicacion_nvd:  vuln?.published ?? null,
    fecha_ingesta_pipeline: new Date().toISOString(),
    cve_description:        vuln?.descriptions?.find(d => d.lang === 'en')?.value ?? '',
    nvd_url:                `https://nvd.nist.gov/vuln/detail/${webhook.cve_id}`,
    epss_url:               `https://api.first.org/data/v1/epss?cve=${webhook.cve_id}`
  }
}];
